    capacity = get(instance, "capacity", "vehicle_capacity", "cap", default=None)
    demands = get(instance, "demands", "demand", default=None)
    coords = get(instance, "coords", "coordinates", "points", default=None)
    dist_matrix = get(instance, "distance_matrix", "dist_matrix", "matrix", default=None)

    customers = None
    if isinstance(instance, dict):
        if "customers" in instance:
            customers = list(instance["customers"])
        elif "nodes" in instance:
            customers = list(instance["nodes"])
        elif isinstance(demands, dict):
            customers = list(demands.keys())
        elif isinstance(coords, dict):
            customers = list(coords.keys())
        elif isinstance(dist_matrix, dict):
            customers = list(dist_matrix.keys())

    if customers is None:
        customers = []

    customers = [c for c in customers if c != depot]
    seen = set()
    uniq = []
    for c in customers:
        if c not in seen:
            seen.add(c)
            uniq.append(c)
    customers = uniq

    def demand_of(i):
        if demands is None:
            return 0
        if isinstance(demands, dict):
            return demands.get(i, 0)
        if isinstance(demands, (list, tuple)) and isinstance(i, int) and 0 <= i < len(demands):
            return demands[i]
        return 0

    def coord_of(i):
        if coords is None:
            return None
        if isinstance(coords, dict):
            return coords.get(i, None)
        if isinstance(coords, (list, tuple)) and isinstance(i, int) and 0 <= i < len(coords):
            return coords[i]
        return None

    def dist(i, j):
        if i == j:
            return 0
        if dist_matrix is not None:
            if isinstance(dist_matrix, dict):
                row = dist_matrix.get(i)
                if isinstance(row, dict) and j in row:
                    return row[j]
                row = dist_matrix.get(j)
                if isinstance(row, dict) and i in row:
                    return row[i]
            elif isinstance(dist_matrix, (list, tuple)):
                return dist_matrix[i][j]
        ci = coord_of(i)
        cj = coord_of(j)
        if ci is not None and cj is not None:
            return euclid(ci, cj)
        return 0

    # ---------- capacity ----------
    if capacity is None:
        total = 0
        for c in customers:
            total += max(0, demand_of(c))
        capacity = total if total > 0 else 10 ** 18

    # ---------- initial singleton routes ----------
    routes = [[c] for c in customers]
    route_load = [demand_of(c) for c in customers]

    # ---------- Clarke-Wright style savings merge ----------
    # We only merge at route ends to keep it deterministic and cheap.
    changed = True
    while changed:
        changed = False
        best = None  # (saving, ra, rb, orient)
        # map customer -> route index on each iteration
        pos = {}
        for idx, r in enumerate(routes):
            if not r:
                continue
            pos[r[0]] = (idx, "start")
            pos[r[-1]] = (idx, "end")

        n = len(routes)
        for a in range(n):
            ra = routes[a]
            if not ra:
                continue
            for b in range(a + 1, n):
                rb = routes[b]
                if not rb:
                    continue
                la = route_load[a]
                lb = route_load[b]
                if la + lb > capacity:
                    continue

                a0, a1 = ra[0], ra[-1]
                b0, b1 = rb[0], rb[-1]

                candidates = [
                    (dist(depot, a1) + dist(depot, b0) - dist(a1, b0), 0),  # ra + rb
                    (dist(depot, a1) + dist(depot, b1) - dist(a1, b1), 1),  # ra + rev(rb)
                    (dist(depot, a0) + dist(depot, b0) - dist(a0, b0), 2),  # rev(ra) + rb
                    (dist(depot, a0) + dist(depot, b1) - dist(a0, b1), 3),  # rev(ra) + rev(rb)
                ]
                candidates.sort(key=lambda x: (-x[0], x[1]))
                saving, orient = candidates[0]
                if saving > 1e-12:
                    cand = (saving, a, b, orient)
                    if best is None or cand > best:
                        best = cand

        if best is not None:
            _, a, b, orient = best
            ra = routes[a]
            rb = routes[b]
            if orient == 0:
                merged = ra + rb
            elif orient == 1:
                merged = ra + rb[::-1]
            elif orient == 2:
                merged = ra[::-1] + rb
            else:
                merged = ra[::-1] + rb[::-1]
            routes[a] = merged
            route_load[a] += route_load[b]
            routes[b] = []
            route_load[b] = 0
            changed = True

    routes = [norm_route(r) for r in routes if r]

    # ---------- repair: ensure every customer assigned exactly once ----------
    assigned = set()
    for r in routes:
        for c in r:
            assigned.add(c)
    missing = [c for c in customers if c not in assigned]
    for c in missing:
        routes.append([c])

    # remove duplicates across routes by first occurrence
    seen = set()
    repaired = []
    for r in routes:
        nr = []
        for c in r:
            if c not in seen:
                seen.add(c)
                nr.append(c)
        if nr:
            repaired.append(nr)
    routes = repaired

    # ---------- local search: intra-route 2-opt ----------
    def route_cost(r):
        if not r:
            return 0
        s = dist(depot, r[0]) + dist(r[-1], depot)
        for i in range(len(r) - 1):
            s += dist(r[i], r[i + 1])
        return s

    improved = True
    while improved:
        improved = False
        for idx, r in enumerate(routes):
            m = len(r)
            if m < 4:
                continue
            best_gain = 0
            best_i = best_j = None
            base = route_cost(r)
            for i in range(m - 2):
                for j in range(i + 2, m):
                    nr = r[:i + 1] + r[i + 1:j + 1][::-1] + r[j + 1:]
                    gain = base - route_cost(nr)
                    if gain > best_gain + 1e-12:
                        best_gain = gain
                        best_i, best_j = i, j
            if best_gain > 1e-12:
                routes[idx] = r[:best_i + 1] + r[best_i + 1:best_j + 1][::-1] + r[best_j + 1:]
                improved = True

    # ---------- local search: inter-route relocate ----------
    def load_of(r):
        s = 0
        for c in r:
            s += demand_of(c)
        return s

    route_load = [load_of(r) for r in routes]
    improved = True
    while improved:
        improved = False
        best_move = None  # (delta, a, i, b, pos)
        for a in range(len(routes)):
            ra = routes[a]
            if not ra:
                continue
            for i, c in enumerate(ra):
                dc = demand_of(c)
                # removal delta
                left = depot if i == 0 else ra[i - 1]
                right = depot if i == len(ra) - 1 else ra[i + 1]
                rem = dist(left, c) + dist(c, right) - dist(left, right)
                for b in range(len(routes)):
                    if a == b:
                        continue
                    rb = routes[b]
                    if route_load[b] + dc > capacity:
                        continue
                    for pos in range(len(rb) + 1):
                        before = depot if pos == 0 else rb[pos - 1]
                        after = depot if pos == len(rb) else rb[pos]
                        add = dist(before, c) + dist(c, after) - dist(before, after)
                        delta = rem - add
                        if delta > 1e-12:
                            cand = (delta, a, i, b, pos)
                            if best_move is None or cand > best_move:
                                best_move = cand
        if best_move is not None:
            _, a, i, b, pos = best_move
            c = routes[a].pop(i)
            route_load[a] -= demand_of(c)
            routes[b].insert(pos, c)
            route_load[b] += demand_of(c)
            if not routes[a]:
                routes.pop(a)
                route_load.pop(a)
            improved = True

    # ---------- final cleanup / guarantee coverage ----------
    used = set()
    final_routes = []
    for r in routes:
        nr = []
        for c in r:
            if c not in used:
                used.add(c)
                nr.append(c)
        if nr:
            final_routes.append(nr)

    missing = [c for c in customers if c not in used]
    for c in missing:
        final_routes.append([c])

    # Last deterministic pack: try to append missing-alone routes into existing feasible routes
    singles = [r for r in final_routes if len(r) == 1]
    others = [r for r in final_routes if len(r) != 1]
    final_routes = others + singles

    # Ensure no depot appears
    cleaned = []
    for r in final_routes:
        nr = [c for c in r if c != depot]
        if nr:
            cleaned.append(nr)

    return cleaned
